4	const NAMED_ENTITIES = new Map([
5	  ['amp', '&'],
6	  ['lt', '<'],
7	  ['gt', '>'],
8	  ['quot', '"'],
9	  ['apos', "'"],
10	  ['nbsp', '\u00a0'],
11	  ['copy', '©'],
12	  ['reg', '®'],
13	  ['trade', '™'],
14	  ['hellip', '…'],
15	  ['mdash', '—'],
16	  ['ndash', '–'],
17	]);
18	
19	function isUnicodeWhitespaceChar(ch) {
20	  // 单字符 trim 可覆盖 NBSP 等 Unicode 空白。
21	  return ch.trim() === '';
22	}
