24	/**
25	 * CRLF/CR → LF；tab 按 4 列制表位展开（对齐到 4 的倍数列，列从行首计）。
26	 */
27	export function normalizeText(value) {
28	  const input = String(value);
29	  let out = '';
30	  let col = 0;
31	  let i = 0;
32	  const n = input.length;
33	  while (i < n) {
34	    const ch = input[i];
35	    if (ch === '\r') {
36	      if (i + 1 < n && input[i + 1] === '\n') {
37	        i += 1;
38	      }
39	      out += '\n';
40	      col = 0;
41	    } else if (ch === '\n') {
42	      out += '\n';
43	      col = 0;
44	    } else if (ch === '\t') {
45	      const spaces = 4 - (col % 4);
46	      out += '    '.slice(0, spaces);
47	      col += spaces;
48	    } else {
49	      out += ch;
50	      col += 1;
51	    }
52	    i += 1;
53	  }
54	  return out;
55	}
