57	/**
58	 * 行为空行：空或仅含 Unicode 空白字符。
59	 */
60	export function isBlankLine(line) {
61	  const s = String(line);
62	  for (let i = 0; i < s.length; i += 1) {
63	    if (!isUnicodeWhitespaceChar(s[i])) {
64	      return false;
65	    }
66	  }
67	  return true;
68	}
