70	/**
71	 * 去除文本首尾的空白行（中间的空白行保留）。
72	 */
73	export function stripOuterBlankLines(text) {
74	  const lines = String(text).split('\n');
75	  let start = 0;
76	  let end = lines.length;
77	  while (start < end && isBlankLine(lines[start])) {
78	    start += 1;
79	  }
80	  while (end > start && isBlankLine(lines[end - 1])) {
81	    end -= 1;
82	  }
83	  return lines.slice(start, end).join('\n');
84	}
