86	/**
87	 * 统计行首可剥空白（空格与 NBSP）数量。
88	 */
89	export function countLeadingSpaces(line) {
90	  const s = String(line);
91	  let count = 0;
92	  while (count < s.length) {
93	    const ch = s[count];
94	    if (ch === ' ' || ch === '\u00a0') {
95	      count += 1;
96	    } else {
97	      break;
98	    }
99	  }
100	  return count;
101	}
