103	/**
104	 * 代码/属性转义：& < > " 全部转义。
105	 */
106	export function escapeHtmlAll(value) {
107	  const s = String(value);
108	  let out = '';
109	  for (let i = 0; i < s.length; i += 1) {
110	    const ch = s[i];
111	    if (ch === '&') {
112	      out += '&amp;';
113	    } else if (ch === '<') {
114	      out += '&lt;';
115	    } else if (ch === '>') {
116	      out += '&gt;';
117	    } else if (ch === '"') {
118	      out += '&quot;';
119	    } else {
120	      out += ch;
121	    }
122	  }
123	  return out;
124	}
