126	/**
127	 * 属性值转义（与 escapeHtmlAll 一致：& < > " 全部转义）。
128	 */
129	export function escapeAttribute(value) {
130	  return escapeHtmlAll(value);
131	}
132	
133	function isAsciiDigit(ch) {
134	  return ch >= '0' && ch <= '9';
135	}
136	
137	function isAsciiLetter(ch) {
138	  return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');
139	}
140	
141	function isHexDigit(ch) {
142	  return isAsciiDigit(ch) || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
143	}
144	
145	/**
146	 * 尝试在 text[index]（应为 '&'）处解析一个 HTML 实体。
147	 * 返回 { raw, decoded, end }（end 为实体之后的位置），不是合法实体时返回 null。
148	 * 支持命名实体（见 NAMED_ENTITIES）与十进制（&#123;）/十六进制（&#x1F;）数字实体。
149	 */
150	export function parseEntityAt(text, index) {
151	  const s = String(text);
152	  const n = s.length;
153	  if (index < 0 || index >= n || s[index] !== '&') {
154	    return null;
155	  }
156	  let i = index + 1;
157	  if (i >= n) {
158	    return null;
159	  }
160	  if (s[i] === '#') {
161	    // 数字实体
162	    i += 1;
163	    let isHex = false;
164	    if (i < n && (s[i] === 'x' || s[i] === 'X')) {
165	      isHex = true;
166	      i += 1;
167	    }
168	    const digitStart = i;
169	    while (i < n && (isHex ? isHexDigit(s[i]) : isAsciiDigit(s[i]))) {
170	      i += 1;
171	    }
172	    if (i === digitStart || i >= n || s[i] !== ';') {
173	      return null;
174	    }
175	    const digits = s.slice(digitStart, i);
176	    let codePoint;
177	    if (isHex) {
178	      codePoint = 0;
179	      for (let k = 0; k < digits.length; k += 1) {
180	        const c = digits[k];
181	        let v;
182	        if (isAsciiDigit(c)) {
183	          v = c.charCodeAt(0) - 48;
184	        } else if (c >= 'a' && c <= 'f') {
185	          v = c.charCodeAt(0) - 87;
186	        } else {
187	          v = c.charCodeAt(0) - 55;
188	        }
189	        codePoint = codePoint * 16 + v;
190	        if (codePoint > 0x10ffff) {
191	          return null;
192	        }
193	      }
194	    } else {
195	      codePoint = 0;
196	      for (let k = 0; k < digits.length; k += 1) {
197	        codePoint = codePoint * 10 + (digits[k].charCodeAt(0) - 48);
198	        if (codePoint > 0x10ffff) {
199	          return null;
200	        }
201	      }
202	    }
203	    let decoded;
204	    try {
205	      decoded = String.fromCodePoint(codePoint);
206	    } catch {
207	      return null;
208	    }
209	    return { raw: s.slice(index, i + 1), decoded, end: i + 1 };
210	  }
211	  // 命名实体：字母数字组成，分号结尾
212	  const nameStart = i;
213	  while (i < n && (isAsciiLetter(s[i]) || isAsciiDigit(s[i]))) {
214	    i += 1;
215	  }
216	  if (i === nameStart || i >= n || s[i] !== ';') {
217	    return null;
218	  }
219	  const name = s.slice(nameStart, i);
220	  if (!NAMED_ENTITIES.has(name)) {
221	    return null;
222	  }
223	  return { raw: s.slice(index, i + 1), decoded: NAMED_ENTITIES.get(name), end: i + 1 };
224	}
