226	/**
227	 * 普通文本转义：裸 & → &amp;，合法实体（&name; &#123; &#x1F;）整体保留，< > 转义。
228	 */
229	export function escapeTextPreservingEntities(value) {
230	  const s = String(value);
231	  let out = '';
232	  let i = 0;
233	  while (i < s.length) {
234	    const ch = s[i];
235	    if (ch === '&') {
236	      const entity = parseEntityAt(s, i);
237	      if (entity !== null) {
238	        out += entity.raw;
239	        i = entity.end;
240	      } else {
241	        out += '&amp;';
242	        i += 1;
243	      }
244	    } else if (ch === '<') {
245	      out += '&lt;';
246	      i += 1;
247	    } else if (ch === '>') {
248	      out += '&gt;';
249	      i += 1;
250	    } else {
251	      out += ch;
252	      i += 1;
253	    }
254	  }
255	  return out;
256	}
