258	/**
259	 * 解码字符串中所有可识别实体；无法识别的 & 原样保留。
260	 */
261	export function decodeEntities(value) {
262	  const s = String(value);
263	  let out = '';
264	  let i = 0;
265	  while (i < s.length) {
266	    if (s[i] === '&') {
267	      const entity = parseEntityAt(s, i);
268	      if (entity !== null) {
269	        out += entity.decoded;
270	        i = entity.end;
271	        continue;
272	      }
273	    }
274	    out += s[i];
275	    i += 1;
276	  }
277	  return out;
278	}
