280	/**
281	 * NFKD 规范化后删除所有非 ASCII 字符（效果如 Python 的 encode('ascii', 'ignore')）。
282	 */
283	export function asciiFold(value) {
284	  const normalized = String(value).normalize('NFKD');
285	  let out = '';
286	  for (const ch of normalized) {
287	    if (ch.codePointAt(0) <= 0x7f) {
288	      out += ch;
289	    }
290	  }
291	  return out;
292	}
