294	/**
295	 * 序列化属性（对象或 Map）：按属性名字典序输出 `k="v"` 列表，空格连接。
296	 * 值为 null/undefined 时跳过该属性；其他值经 String() 后按属性规则转义。
297	 */
298	export function serializeAttributes(attrs) {
299	  if (attrs === null || attrs === undefined) {
300	    return '';
301	  }
302	  const entries = [];
303	  if (attrs instanceof Map) {
304	    for (const [key, val] of attrs) {
305	      if (val === null || val === undefined) {
306	        continue;
307	      }
308	      entries.push([String(key), String(val)]);
309	    }
310	  } else {
311	    for (const key of Object.keys(attrs)) {
312	      const val = attrs[key];
313	      if (val === null || val === undefined) {
314	        continue;
315	      }
316	      entries.push([String(key), String(val)]);
317	    }
318	  }
319	  entries.sort((a, b) => {
320	    if (a[0] < b[0]) {
321	      return -1;
322	    }
323	    if (a[0] > b[0]) {
324	      return 1;
325	    }
326	    return 0;
327	  });
328	  const parts = [];
329	  for (const [key, val] of entries) {
330	    parts.push(key + '="' + escapeAttribute(val) + '"');
331	  }
332	  return parts.join(' ');
333	}
